<?php if (!empty($modoImpressao)): ?><table><thead><tr><th>Data</th><th>Utilizador</th><th>Ação</th><th>Tabela</th><th>Registo</th><th>IP</th></tr></thead><tbody><?php foreach($logs as $log): ?><tr><td><?=htmlspecialchars($log['criado_em'])?></td><td><?=htmlspecialchars($log['usuario_nome']??'Sistema')?></td><td><?=htmlspecialchars($log['acao'])?></td><td><?=htmlspecialchars($log['tabela_afetada']??'')?></td><td><?=htmlspecialchars($log['registo_id']??'')?></td><td><?=htmlspecialchars($log['ip_origem']??'')?></td></tr><?php endforeach?></tbody></table><?php return; endif; ?>
<div class="modulo-cabecalho logs-cabecalho"><div><h1><i class="fa-solid fa-clipboard-list"></i> Logs de auditoria</h1><p>Consulte operações registadas no sistema. Os logs não podem ser alterados ou eliminados.</p></div><a class="btn btn-success" href="<?=URL_BASE?>/logs/exportar?<?=htmlspecialchars(http_build_query($filtros))?>"><i class="fa-solid fa-file-csv"></i> Exportar CSV</a></div>
<section class="filtros-logs"><form method="get" action="<?=URL_BASE?>/logs/index"><label>Utilizador<select name="usuario_id"><option value="">Todos</option><?php foreach($usuarios as $u):?><option value="<?=$u['id']?>" <?=$filtros['usuario_id']==$u['id']?'selected':''?>><?=htmlspecialchars($u['nome'])?></option><?php endforeach?></select></label><label>Ação<input name="acao" placeholder="Ex.: criar" value="<?=htmlspecialchars($filtros['acao'])?>"></label><label>Tabela<input name="tabela_afetada" placeholder="Ex.: transacoes" value="<?=htmlspecialchars($filtros['tabela_afetada'])?>"></label><label>De<input type="date" name="inicio" value="<?=htmlspecialchars($filtros['inicio'])?>"></label><label>Até<input type="date" name="fim" value="<?=htmlspecialchars($filtros['fim'])?>"></label><button class="btn btn-primary"><i class="fa-solid fa-filter"></i> Filtrar</button></form></section>
<section class="tabela-logs"><div class="tabela-scroll"><table><thead><tr><th>Data e hora</th><th>Utilizador</th><th>Ação</th><th>Origem</th><th>Registo</th><th></th></tr></thead><tbody><?php if(empty($logs)):?><tr><td colspan="6" class="sem-logs">Não foram encontrados logs para estes filtros.</td></tr><?php endif;foreach($logs as $log):?><tr><td><?=htmlspecialchars(date('d/m/Y H:i',strtotime($log['criado_em'])))?></td><td><?=htmlspecialchars($log['usuario_nome']??'Sistema')?></td><td><span class="acao-log"><?=htmlspecialchars($log['acao'])?></span></td><td><?=htmlspecialchars($log['tabela_afetada']??'—')?></td><td>#<?=htmlspecialchars($log['registo_id']??'—')?></td><td><button class="btn btn-outline btn-sm" onclick="verDetalhes(<?= (int)$log['id']?>)">Detalhes</button></td></tr><?php endforeach?></tbody></table></div><?php if(($paginacao['paginas']??1)>1):?><nav class="paginacao"><?php for($p=1;$p<=$paginacao['paginas'];$p++):?><a class="<?=((int)($_GET['pagina']??1)===$p)?'ativo':''?>" href="<?=URL_BASE?>/logs/index?<?=htmlspecialchars(http_build_query(array_merge($filtros,['pagina'=>$p])))?>"><?=$p?></a><?php endfor?></nav><?php endif?></section><section id="detalhes-log" class="detalhes-log" hidden><div><h2>Alterações registadas</h2><button type="button" onclick="document.getElementById('detalhes-log').hidden=true">×</button></div><pre></pre></section><style>.logs-cabecalho{display:flex;justify-content:space-between;gap:16px;align-items:flex-start;margin-bottom:22px}.modulo-cabecalho h1{margin:0;color:var(--navy-deep);font-size:26px}.modulo-cabecalho h1 i{color:var(--green);margin-right:8px}.modulo-cabecalho p{color:var(--muted);margin:6px 0}.filtros-logs,.tabela-logs{background:#fff;border:1px solid var(--border);border-radius:14px;padding:18px;margin-bottom:18px}.filtros-logs form{display:grid;grid-template-columns:repeat(5,minmax(110px,1fr)) auto;gap:12px;align-items:end}.filtros-logs label{display:grid;gap:5px;font-size:12px;font-weight:700}.filtros-logs input,.filtros-logs select{padding:9px;border:1px solid var(--border);border-radius:7px;background:#fff}.tabela-scroll{overflow:auto}.tabela-logs table{width:100%;border-collapse:collapse;font-size:13px}.tabela-logs th{background:var(--navy-deep);color:#fff;text-align:left;padding:11px}.tabela-logs td{padding:12px;border-bottom:1px solid var(--border)}.acao-log{background:rgba(34,197,94,.12);color:var(--green-dark);border-radius:20px;padding:4px 8px;font-size:11px;font-weight:700}.sem-logs{text-align:center!important;color:var(--muted);padding:30px!important}.paginacao{display:flex;gap:6px;padding-top:15px}.paginacao a{border:1px solid var(--border);padding:6px 10px;border-radius:6px;text-decoration:none;color:var(--ink)}.paginacao .ativo{background:var(--green);color:#fff}.detalhes-log{background:#fff;border:1px solid var(--border);border-radius:14px;padding:20px}.detalhes-log>div{display:flex;justify-content:space-between}.detalhes-log h2{margin:0}.detalhes-log button{border:0;background:none;font-size:22px;cursor:pointer}.detalhes-log pre{padding:14px;background:#10263f;color:#d7f3e0;border-radius:8px;overflow:auto}@media(max-width:900px){.filtros-logs form{grid-template-columns:repeat(2,1fr)}.logs-cabecalho{flex-direction:column}}</style><script>function verDetalhes(id){fetch('<?=URL_BASE?>/logs/detalhes/'+id).then(r=>r.json()).then(d=>{const el=document.getElementById('detalhes-log');el.hidden=false;el.querySelector('pre').textContent=JSON.stringify({dados_antigos:d.dados_antigos,dados_novos:d.dados_novos},null,2)}).catch(()=>alert('Não foi possível carregar os detalhes do log.'))}</script>
